<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';
require_permission('video_categories.manage');
if(is_post()){verify_csrf();try{$action=(string)input('action');$pdo=db();$pdo->beginTransaction();if($action==='create'){$name=trim((string)input('name'));$limit=(int)input('capacity_limit',500);if($name===''||strlen($name)>190||$limit<1||$limit>100000)throw new InvalidArgumentException('Valid category name and capacity are required.');$slug='cat_'.preg_replace('/[^a-z0-9]+/','_',strtolower($name));$slug=trim($slug,'_').'_'.bin2hex(random_bytes(2));$pdo->prepare('INSERT INTO video_categories(name,slug,character_name,character_asset_url,channel_url,teaser_video_id,broadcast_message,overlay_asset_url,capacity_limit,status,created_by) VALUES(?,?,?,?,?,?,?, ?,?,"ACTIVE",?)')->execute([$name,trim((string)input('character_name'))?:null,trim((string)input('character_asset_url'))?:null,trim((string)input('channel_url'))?:null,trim((string)input('teaser_video_id'))?:null,trim((string)input('broadcast_message'))?:null,trim((string)input('overlay_asset_url'))?:null,$limit,admin()['id']]);$record=(string)$pdo->lastInsertId();audit_log((int)admin()['id'],'CATEGORY_CREATED','video_categories',$record);}elseif($action==='toggle'){$id=(int)input('id');$pdo->prepare('UPDATE video_categories SET status=IF(status="ACTIVE","INACTIVE","ACTIVE") WHERE id=?')->execute([$id]);$record=(string)$id;audit_log((int)admin()['id'],'CATEGORY_KILL_SWITCH','video_categories',$record,null,['status'=>'TOGGLED']);}elseif($action==='broadcast'){$id=(int)input('id');$s=$pdo->prepare('SELECT broadcast_message FROM video_categories WHERE id=? AND status="ACTIVE"');$s->execute([$id]);$message=trim((string)input('message'))?:((string)$s->fetchColumn());if($message==='')throw new InvalidArgumentException('Broadcast message is required.');$pdo->prepare('INSERT INTO category_broadcasts(category_id,topic,message,status,created_by) VALUES(?, ?, ?,"QUEUED",?)')->execute([$id,'category_'.$id,$message,admin()['id']]);$record=(string)$pdo->lastInsertId();audit_log((int)admin()['id'],'CATEGORY_BROADCAST_QUEUED','category_broadcasts',$record);}else throw new InvalidArgumentException('Invalid category action.');$pdo->commit();flash('success','Category hub change saved.');}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('/admin/categories/index.php');}
$categories=db()->query('SELECT c.*,(SELECT COUNT(*) FROM qr_campaigns q WHERE q.category_id=c.id) qr_count FROM video_categories c ORDER BY c.id DESC')->fetchAll();$pageTitle='Category & character hub';$pageSubtitle='Theme buckets, QR capacity, kill-switch and targeted notices';require APP_ROOT.'/includes/header.php';?><div class="category-hub"><header class="hub-banner"><h2>Category & Character Master Hub</h2><span>Dynamic category linking & master kill-switch</span></header>
<section class="panel"><div class="panel-head"><div><h2>Create category bucket</h2><p class="help">Assets are stored as controlled URLs/paths; upload them to your protected asset storage.</p></div></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="field"><label>Bucket name</label><input name="name" maxlength="190" placeholder="Patna Zoo & Wildlife Safari Hunt" required></div><div class="field"><label>Capacity limit</label><input name="capacity_limit" type="number" min="1" max="100000" value="500" required></div><div class="field"><label>Character / vector avatar</label><input name="character_name" placeholder="Zoo Explorer Mascot (Cheetah 3D Vector)"></div><div class="field"><label>Character asset URL/path</label><input name="character_asset_url" type="url" placeholder="https://cdn.example.com/zoo.svg"></div><div class="field"><label>Linked YouTube channel</label><input name="channel_url" type="url" placeholder="https://youtube.com/@PatnaZooHuntLive"></div><div class="field"><label>Teaser video ID</label><input name="teaser_video_id" placeholder="zoo_safari_teaser_v1"></div><div class="field"><label>Overlay poster URL/path</label><input name="overlay_asset_url" placeholder="/uploads/overlays/zoo.png"></div><div class="field full"><label>Target broadcast message</label><textarea name="broadcast_message" maxlength="500" placeholder="Zoo Safari Alert: hidden spots are live…"></textarea></div><div class="field full"><button class="btn">Create active bucket</button></div></form></section>
<section class="panel"><h2>Configured buckets</h2><div class="table-wrap"><table><thead><tr><th>Bucket</th><th>Character</th><th>Channel/video</th><th>QR capacity</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><strong><?=e($c['name'])?></strong><br><small><?=e($c['slug'])?></small></td><td><?=e($c['character_name']??'—')?></td><td><?=e($c['channel_url']??'—')?><br><small><?=e($c['teaser_video_id']??'—')?></small></td><td><?=e($c['qr_count'])?> / <?=e($c['capacity_limit'])?></td><td><span class="badge <?=strtolower(e($c['status']))?>"><?=e($c['status'])?></span></td><td><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=e($c['id'])?>"><button class="btn small <?=($c['status']==='ACTIVE'?'danger':'success')?>"><?=($c['status']==='ACTIVE'?'Deactivate':'Activate')?></button></form><?php if($c['status']==='ACTIVE'):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="action" value="broadcast"><input type="hidden" name="id" value="<?=e($c['id'])?>"><input name="message" placeholder="Use saved notice"><button class="btn small secondary">Send notice</button></form><?php endif?></div></td></tr><?php endforeach?></tbody></table><?php if(!$categories):?><div class="empty">No category buckets configured.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
